<header class="admin-page-head content-width"><div><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/admin/dashboard">Dashboard</a><span>/</span><span>Laporan</span></nav><h1>Laporan simulasi</h1><p>Seluruh nominal berasal dari pembayaran dummy dan bukan pendapatan nyata.</p></div><form class="report-filter" action="/admin/reports" method="get"><label>Dari<input name="from" type="date" value="<?= e($from) ?>"></label><label>Sampai<input name="to" type="date" value="<?= e($to) ?>"></label><button class="btn btn-dark" type="submit">Terapkan</button></form></header>
<section class="content-width report-section"><div class="report-metrics"><div><span>Order</span><strong><?= (int) $summary['order_count'] ?></strong></div><div><span>Kunjungan</span><strong><?= (int) $summary['visit_count'] ?></strong></div><div><span>QRIS simulasi</span><strong><?= (int) $summary['qris_count'] ?></strong></div><div><span>Tunai simulasi</span><strong><?= (int) $summary['cash_count'] ?></strong></div><div><span>Total nominal simulasi</span><strong><?= e(rupiah((int) $summary['simulated_total'])) ?></strong></div></div>
<div class="report-grid"><div><h2>Transaksi</h2><div class="report-table-wrap"><table><thead><tr><th>Order</th><th>Meja</th><th>Pelanggan</th><th>Metode</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td><?= e($order['order_code']) ?><small><?= e($order['created_at']) ?></small></td><td><?= e($order['table_code']) ?></td><td><?= e($order['customer_name_snapshot']) ?></td><td><?= $order['method'] === 'qris_sim' ? 'QRIS' : 'Tunai' ?></td><td><?= e($order['status']) ?></td><td><?= e(rupiah((int) $order['total_idr'])) ?></td></tr><?php endforeach; ?></tbody></table></div></div><aside><h2>Menu terjual</h2><?php foreach ($top_items as $item): ?><div class="table-usage"><span><?= e($item['menu_name_snapshot']) ?></span><strong><?= (int) $item['quantity_sold'] ?> item</strong></div><?php endforeach; ?><?php if ($top_items === []): ?><p class="text-muted small">Belum ada item pada rentang ini.</p><?php endif; ?><h2 class="mt-4">Penggunaan meja</h2><?php foreach ($table_usage as $usage): ?><div class="table-usage"><span><?= e($usage['table_code']) ?></span><strong><?= (int) $usage['visit_count'] ?> kunjungan</strong></div><?php endforeach; ?></aside></div></section>
